    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) {
        return 0;
    }
    if (hasApple == null || hasApple.length != n) {
        throw new IllegalArgumentException("hasApple array length must be equal to n");
    }
    if (edges == null) {
        if (n == 1) {
            return 0;
        } else {
            throw new IllegalArgumentException("edges cannot be null for n > 1");
        }
    }
    if (edges.length != n - 1) {
        throw new IllegalArgumentException("edges length must be n-1 for a tree");
    }

    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] edge : edges) {
        if (edge == null || edge.length != 2) {
            throw new IllegalArgumentException("Each edge must contain exactly two nodes");
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw new IllegalArgumentException("Edge node indices out of bounds");
        }
        graph[u].add(v);
        graph[v].add(u);
    }

    int[] total = new int[1];
    dfs(0, -1, graph, hasApple, total);
    return total[0];
}

private boolean dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple, int[] total) {
    boolean has = hasApple[node];
    for (int neighbor : graph[node]) {
        if (neighbor == parent) {
            continue;
        }
        boolean childHas = dfs(neighbor, node, graph, hasApple, total);
        if (childHas) {
            total[0] += 2;
            has = true;
        }
    }
    return has;
}

