    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    dp[0] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int i = 0; i < n; i++) {
        int val = nums[i];
        int limit = Math.min(i + 1, maxK);
        for (int k = limit; k >= 1; k--) {
            java.util.HashSet<Integer> prev = dp[k - 1];
            if (prev == null) continue;
            java.util.HashSet<Integer> curr = dp[k];
            if (curr == null) curr = new java.util.HashSet<>();
            for (int s : prev) {
                curr.add(s + val);
            }
            dp[k] = curr;
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((long) total * k % n != 0) continue;
        int target = (int) ((long) total * k / n);
        java.util.HashSet<Integer> set = dp[k];
        if (set != null && set.contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // You can start at step 1 (the top), so no cost is needed.
        return 0;
    }
    long[] dp = new long[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        long fromPrev = dp[i - 1] + cost[i - 1];
        long fromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(fromPrev, fromPrevPrev);
    }
    // The result fits in int as per problem constraints; cast safely.
    return (int) dp[n];
}

