public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    // k must be less than 63 to avoid overflow in 1L << k
    if (k >= 63) {
        return false;
    }
    long mask = (1L << k) - 1;
    java.util.Set<Long> seen = new java.util.HashSet<>();
    long val = 0;
    // Build the first window
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen.add(val);
    // Slide the window
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        seen.add(val);
    }
    long total = 1L << k;
    return seen.size() == total;
}

