public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int size = fib.size();
        long next = (long) fib.get(size - 1) + fib.get(size - 2);
        if (next > k) {
            break;
        }
        fib.add((int) next);
    }
    int count = 0;
    int remaining = k;
    // Greedy: pick largest Fibonacci numbers first
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fib.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
