    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            // Check if c and last are same letter with opposite cases
            if (Math.abs(c - last) == 32 && Character.toLowerCase(c) == Character.toLowerCase(last)) {
                stack.deleteCharAt(len - 1); // remove the pair
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = new int[1];
    java.util.HashSet<String> used = new java.util.HashSet<>();
    dfs(s, 0, used, max);
    return max[0];
}

private void dfs(String s, int index, java.util.HashSet<String> used, int[] max) {
    if (index == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int len = 1; len <= s.length() - index; len++) {
        String sub = s.substring(index, index + len);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, index + len, used, max);
            used.remove(sub);
        }
    }
}

