public String getSmallestString(int n, int k) {
    // Validate input: each character contributes at least 1 and at most 26.
    if (n <= 0 || k <= 0) {
        return "";
    }
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) {
        return "";
    }

    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        int remainingPositions = n - i - 1;
        // Try the smallest possible value for this position.
        for (int val = 1; val <= 26; val++) {
            int remainingSum = k - val;
            if (remainingSum < remainingPositions) {
                // Even if we set all remaining to 'a', sum too small.
                continue;
            }
            if (remainingSum > remainingPositions * 26) {
                // Even if we set all remaining to 'z', sum too large.
                continue;
            }
            // This value works.
            sb.append((char) ('a' + val - 1));
            k -= val;
            break;
        }
    }
    return sb.toString();
}

