public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int bitCount = 0;
        for (int num : nums) {
            bitCount += (num >> i) & 1;
        }
        if ((bitCount % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0 || low > high) {
        return result;
    }
    int startLow = Math.max(low, 0);
    // Handle 0 separately
    if (startLow == 0) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        if (d >= startLow && d <= high) {
            result.add(d);
        }
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        int[] nextDigits = {lastDigit - 1, lastDigit + 1};
        for (int nd : nextDigits) {
            if (nd < 0 || nd > 9) {
                continue;
            }
            long newNum = num * 10 + nd;
            if (newNum > high) {
                continue;
            }
            if (newNum >= startLow) {
                result.add((int) newNum);
            }
            queue.offer(newNum);
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long num = n;
    while (num / factor > 0) {
        long high = num / (factor * 10);
        long cur = (num / factor) % 10;
        long low = num % factor;
        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and has exactly one bit set.
    if (n <= 0) {
        return false;
    }
    // Using the property that n & (n-1) == 0 for powers of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) {
        return 0;
    }
    // Validate that all rows are non-null and have the same length
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            return 0;
        }
    }

    int[][] dpH = new int[m][n];   // horizontal
    int[][] dpV = new int[m][n];   // vertical
    int[][] dpD = new int[m][n];   // diagonal (top-left to bottom-right)
    int[][] dpAD = new int[m][n];  // anti-diagonal (top-right to bottom-left)

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dpH[i][j] = (j > 0 ? dpH[i][j - 1] : 0) + 1;
                dpV[i][j] = (i > 0 ? dpV[i - 1][j] : 0) + 1;
                dpD[i][j] = (i > 0 && j > 0 ? dpD[i - 1][j - 1] : 0) + 1;
                dpAD[i][j] = (i > 0 && j < n - 1 ? dpAD[i - 1][j + 1] : 0) + 1;

                int localMax = Math.max(Math.max(dpH[i][j], dpV[i][j]),
                                        Math.max(dpD[i][j], dpAD[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                dpH[i][j] = dpV[i][j] = dpD[i][j] = dpAD[i][j] = 0;
            }
        }
    }

    return maxLen;
}

