public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    // Use a stack to store indices of bars
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        // Ensure non-negative heights
        int h = Math.max(0, heights[i]);
        while (!stack.isEmpty() && h < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    // Process remaining bars in stack
    while (!stack.isEmpty()) {
        int height = heights[stack.pop()];
        int width = stack.isEmpty() ? n : n - stack.peek() - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    // The result fits in int as per problem statement
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    int maxSum = m + n - 2;
    for (int k = 0; k <= maxSum; k++) {
        int start = Math.max(0, k - (n - 1));
        int end = Math.min(m - 1, k);
        if ((k & 1) == 0) { // even sum: traverse from end to start
            for (int i = end; i >= start; i--) {
                int j = k - i;
                result[idx++] = mat[i][j];
            }
        } else { // odd sum: traverse from start to end
            for (int i = start; i <= end; i++) {
                int j = k - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Find the largest index i such that digits[i] < digits[i + 1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // digits are in non-increasing order, no larger permutation
    }
    // Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse the subarray from i+1 to end
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    try {
        long result = Long.parseLong(new String(digits));
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
        return (int) result;
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
