private static List<String> build(int n, int original) {
    if (n == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (n == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> prev = build(n - 2, original);
    List<String> result = new ArrayList<>();
    for (String s : prev) {
        if (original != n) { // avoid leading zero on the outermost layer
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    // Ensure each point has exactly two coordinates
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check that all points are distinct
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    // Compute cross product to determine collinearity
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

